meta=reg.assign(key=reg.farm_name.str.strip().str.casefold()).merge(farms.assign(key=farms.farm_name.str.strip().str.casefold()),on='key')
START=pd.Timestamp('2024-03-15T00:00:00Z'); END=pd.Timestamp('2024-03-16T00:00:00Z')
maint={
 'FARM_C':[(pd.Timestamp('2024-03-16 08:00').tz_localize('Asia/Tokyo').tz_convert('UTC'),pd.Timestamp('2024-03-16 12:00').tz_localize('Asia/Tokyo').tz_convert('UTC'))],
 'FARM_F':[(pd.Timestamp('2024-03-15 12:00').tz_localize('Europe/Warsaw').tz_convert('UTC'),pd.Timestamp('2024-03-15 14:00').tz_localize('Europe/Warsaw').tz_convert('UTC'))],
}
units={'kwh':1.0,'mwh':1000.0,'wh':.001,'btu':0.0002930710701722222}
res={}
for fid in reg.farm_id:
 p=Path(f'dataset/production_{fid}.csv'); enc='utf-16' if p.read_bytes()[:2]==b'\xff\xfe' else 'utf-8-sig'; head=p.read_text(encoding=enc).splitlines()[3]; sep=';' if head.count(';')>head.count(',') else ','
 df=pd.read_csv(p,skiprows=3,sep=sep,encoding=enc,dtype=str,keep_default_na=False)
 tscol=next(c for c in df if c.strip()=='timestamp'); vcol=cfg[fid]['calibration_data']['value_column_name']
 n0=len(df); df=df.drop_duplicates(subset=[tscol],keep='last'); nd=n0-len(df)
 def parse(s):
  for f in ('%Y-%m-%d %H:%M:%S','%d.%m.%Y %H:%M:%S'):
   try:return datetime.strptime(s,f)
   except ValueError: pass
  return pd.NaT
 local=pd.to_datetime(df[tscol].map(parse)); tz=meta.loc[meta.farm_id.eq(fid),'timezone'].iat[0]; utc=local.dt.tz_localize(tz,ambiguous='NaT',nonexistent='NaT').dt.tz_convert('UTC')
 if sep==';':
  # all legitimate locale-formatted values contain comma
  raw=pd.to_numeric(df[vcol].str.replace('.','',regex=False).str.replace(',','.',regex=False),errors='coerce')
 else: raw=pd.to_numeric(df[vcol],errors='coerce')
 true=raw-float(cfg[fid]['calibration_data']['calibration_offset'])
 valid=utc.notna() & utc.ge(START) & utc.lt(END) & true.notna() & true.ge(0)
 for a,b in maint.get(fid,[]): valid &= ~(utc.ge(a)&utc.lt(b))
 interval=local.sort_values().diff().dropna().mode().iloc[0].total_seconds()/3600
 typ=cfg[fid]['sensor_info']['reading_type'].lower(); unit=cfg[fid]['sensor_info']['unit'].lower()
 factor=interval if typ=='power' else units[unit]
 total=(true[valid]*factor).sum(); res[fid]=round(total)
 print(fid, 'dupdrop',nd,'window valid',valid.sum(),'interval',interval,'maint excl',sum((utc.ge(a)&utc.lt(b)).sum() for a,b in maint.get(fid,[])),'total',total,'round',round(total))
print(res)
